/**
 * Oversized-file ratchet check — pure Node, no shell, no catch.
 *
 * Line-count semantics (visual lines, matches editor line numbers):
 *   countLines(content) = content.split('\n').length, minus 1 iff content
 *   ends with '\n' (a trailing newline does not create a phantom empty
 *   final line; a final line without a trailing newline still counts).
 *   Divergence from `wc -l` is at most 1 line per no-trailing-newline file.
 *
 * The quality-baseline.json snapshot (quality.oversizedFileBaseline) is
 * generated by collectFileLineCounts itself, so gate and snapshot share a
 * single source of truth and are self-consistent by construction.
 *
 * Errors throw — the caller (check-quality-baseline.mjs check 3c) fails
 * loud instead of recording a false PASS.
 */

import { readdirSync, readFileSync, statSync } from 'node:fs';
import { join, relative } from 'node:path';

/** Visual line count of file content (see header for semantics). */
export function countLines(content) {
  if (content.length === 0) return 0;
  const lines = content.split('\n').length;
  return content.endsWith('\n') ? lines - 1 : lines;
}

/**
 * Recursively walk `${rootDir}/src` for .ts/.tsx files and return
 * `[{ path, lines }]` sorted by repo-relative path (posix separators).
 * Throws if rootDir or its src/ subdir is missing (fail loud).
 */
export function collectFileLineCounts(rootDir) {
  const srcDir = join(rootDir, 'src');
  if (!statSync(srcDir, { throwIfNoEntry: false })?.isDirectory()) {
    throw new Error(`collectFileLineCounts: src directory not found at ${srcDir}`);
  }

  const results = [];
  const walk = (dir) => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const full = join(dir, entry.name);
      if (entry.isDirectory()) {
        walk(full);
      } else if (entry.isFile() && (entry.name.endsWith('.ts') || entry.name.endsWith('.tsx'))) {
        results.push({
          path: relative(rootDir, full).split('\\').join('/'),
          lines: countLines(readFileSync(full, 'utf-8')),
        });
      }
    }
  };
  walk(srcDir);

  results.sort((a, b) => a.path.localeCompare(b.path));
  return results;
}

/**
 * Ratchet evaluation against a frozen snapshot.
 *
 * @param {Array<{path: string, lines: number}>} current  all src .ts/.tsx files
 * @param {Record<string, number>} baselineMap  snapshot path → line count
 * @param {number} limit  max allowed lines (quality.maxFileSizeLines)
 * @returns {{ newViolators: string[], grownViolators: string[], prunable: string[], pass: boolean }}
 *
 * Pass iff every file over the limit is already in the snapshot AND its
 * count has not grown. Shrinking is allowed; files that shrank below the
 * limit are listed as prunable (remove via --prune-oversized-snapshot).
 */
export function evaluateOversizedFiles(current, baselineMap, limit) {
  const newViolators = [];
  const grownViolators = [];
  const prunable = [];

  for (const { path, lines } of current) {
    if (lines > limit) {
      if (!(path in baselineMap)) newViolators.push(path);
      else if (lines > baselineMap[path]) grownViolators.push(path);
    }
  }

  const currentByPath = new Map(current.map((f) => [f.path, f.lines]));
  for (const path of Object.keys(baselineMap)) {
    const currentLines = currentByPath.get(path);
    // Missing (deleted) or shrank to/below the limit → snapshot entry is stale.
    if (currentLines === undefined || currentLines <= limit) prunable.push(path);
  }
  prunable.sort();

  return {
    newViolators,
    grownViolators,
    prunable,
    pass: newViolators.length === 0 && grownViolators.length === 0,
  };
}
